    public Object solve(int part, List<Object> args) {
        if (part == 1) return minimaxPath(toIntGrid(args.get(0)));
        return networkDelay(toLongGrid(args.get(0)), ((Number) args.get(1)).intValue(), ((Number) args.get(2)).intValue());
