    @SuppressWarnings("unchecked")
    private static int[][] toIntGrid(Object json) {
        List<Object> rows = (List<Object>) json;
        int[][] out = new int[rows.size()][];
        for (int i = 0; i < out.length; i++) {
            List<Object> row = (List<Object>) rows.get(i);
            out[i] = new int[row.size()];
            for (int j = 0; j < row.size(); j++) out[i][j] = ((Number) row.get(j)).intValue();
        }
        return out;
    }

    @SuppressWarnings("unchecked")
    private static long[][] toLongGrid(Object json) {
        List<Object> rows = (List<Object>) json;
        long[][] out = new long[rows.size()][];
        for (int i = 0; i < out.length; i++) {
            List<Object> row = (List<Object>) rows.get(i);
            out[i] = new long[row.size()];
            for (int j = 0; j < row.size(); j++) out[i][j] = ((Number) row.get(j)).longValue();
        }
        return out;
    }
